<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {usePhasePage} from '../phasePage'
import {copyAttendanceRules,defaultAttendanceRules,sampleAttendanceRules,useRestPolicyText,validAttendanceRules,type AttendanceRuleTemplate,type AttendanceRuleTemplates,type AttendanceRules} from '../restPolicy'
import AttendanceRulesEditor from './AttendanceRulesEditor.vue'
import PhaseStatus from './PhaseStatus.vue'
const props=defineProps<{startNew?:boolean;returnOnSave?:boolean}>(),emit=defineEmits<{saved:[];busy:[value:boolean]}>()
const {api,home,english,loading,busy,failure,notice,load,write}=usePhasePage(),{r}=useRestPolicyText(),items=ref<AttendanceRuleTemplate[]>([]),headOffice=ref(false),reference=ref('11:00')
const draft=ref<{id:string;expectedVersion:number;name:string;enabled:boolean;rules:AttendanceRules}|null>(null)
function refresh(){if(!home.value?.employeeManage)return;void load(()=>api().get<AttendanceRuleTemplates>('/attendance-rule-templates'),data=>{items.value=data.items;headOffice.value=data.headOffice;if(props.startNew&&headOffice.value&&home.value?.headOffice)edit()})}
function edit(item?:AttendanceRuleTemplate){draft.value=item?{id:item.id,expectedVersion:item.version,name:item.name,enabled:item.enabled,rules:copyAttendanceRules(item.rules)}:{id:crypto.randomUUID(),expectedVersion:0,name:'',enabled:true,rules:defaultAttendanceRules(english())};reference.value='11:00'}
function save(){const d=draft.value;if(!d||!headOffice.value||!home.value?.headOffice||!d.name.trim()||!validAttendanceRules(d.rules,1440))return;void write(()=>api().put('/attendance-rule-templates/'+d.id,{expectedVersion:d.expectedVersion,name:d.name.trim(),enabled:d.enabled,rules:d.rules}),()=>{draft.value=null;emit('saved');if(!props.returnOnSave)refresh()})}
watch(busy,value=>emit('busy',value))
onMounted(refresh)
</script>
<template><section class="wf-section wf-policy-settings"><header class="wf-toolbar"><h3>{{r('templates')}}</h3><button v-if="headOffice&&home?.headOffice" type="button" :disabled="loading||busy" @click="edit()">{{r('newTemplate')}}</button></header><p class="wf-hint">{{r('readonly')}}</p><PhaseStatus :loading="loading" :failure="failure" :notice="notice"/><div v-if="!loading" class="wf-policy-list"><div v-for="item in items" :key="item.id" class="wf-form-actions"><span>{{item.name}} · v{{item.version}} <small v-if="!item.enabled">{{r('disabled')}}</small></span><button type="button" :disabled="busy" @click="edit(item)">{{headOffice&&home?.headOffice?r('edit'):r('view')}}</button></div><p v-if="!items.length">{{r('empty')}}</p></div><form v-if="draft" @submit.prevent="save"><fieldset :disabled="busy||!headOffice||!home?.headOffice"><label>{{r('name')}}<input v-model="draft.name" required maxlength="80"></label><label class="wf-check"><input v-model="draft.enabled" type="checkbox">{{r('enabled')}}</label><label>{{r('reference')}}<input v-model="reference" type="time" required></label><p class="wf-hint">{{r('referenceHint')}}</p><button type="button" @click="draft.rules=sampleAttendanceRules(english());reference='11:00'">{{r('sample')}}</button><p class="wf-hint">{{r('sampleHint')}}</p></fieldset><AttendanceRulesEditor v-model="draft.rules" :start-time="reference" :duration="1440" :disabled="busy||!headOffice||!home?.headOffice"/><footer class="wf-form-actions"><button type="button" :disabled="busy" @click="draft=null">{{r('cancel')}}</button><button v-if="headOffice&&home?.headOffice" class="primary" :disabled="busy||!validAttendanceRules(draft.rules,1440)">{{r(props.returnOnSave?'saveAndReturn':'save')}}</button></footer></form></section></template>
<style scoped>.wf-policy-settings{min-width:0}.wf-policy-list .wf-form-actions{justify-content:space-between;border-bottom:1px solid var(--border,#dfe5ed);padding:8px 0}.wf-policy-settings fieldset{min-width:0}</style>
